// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2001, "3-5", [{"author":"И. Рубанов","question":"Из трёх карточек с буквами К, О, Т можно составить три трёхбуквенных слова: кот, ток и кто. А сколько трёхбуквенных слов можно составить из трёх карточек с буквами В, Л, О?","choices":["0","1","2","3","4"],"key":"В","review":["Слова из трёх карточек","Перебери порядок трёх букв, используя В, Л и О по одному разу.","Получаются два слова: «вол» — животное, «лов» — промысел или ловля."]},{"author":"И. Рубанов","question":"Два класса слили в один. Что произошло?","choices":["сливание","слияние","слив","слитие","сливка"],"key":"Б","review":["Объединение двух классов","Когда два отдельных класса объединяются, это называется «слияние классов».","Слово связано с «слить» и «слиться». «Слив» обычно говорят о жидкости или устройстве для её отвода."]},{"author":"П. Аркадьев","question":"Посмотрите на список слов: жир, цирк, щипчики, шип, починка, дорожит. В скольких из них под ударением произносится тот же гласный звук, что и в слове сыр?","choices":["0","2","3","4","5"],"key":"Г","review":["Гласный звук после твёрдого","В словах «жир», «цирк», «шип» и «дорожит» буква и под ударением после твёрдых ж, ц и ш передаёт звук, близкий к [ы].","В «щипчики» и «починка» перед и стоят мягкие согласные. Подходят четыре слова."]},{"author":"И. Рубанов","question":"Даны слова: полька, полка, селёдка, скалка, валко. Сколько из них рифмуется со словом палка?","choices":["0","1","2","3","4"],"key":"В","review":["Рифма на слух","Сравни звуки от ударной гласной до конца слова. «Па́лка» и «ска́лка» имеют одинаковый конец.","В «ва́лко» безударная о звучит так же, как конечное а в «палка». Рифмуются два слова."]},{"author":"К. Кноп","question":"В песне Александра Дулова «Посёлок дачный» есть строчки:\n«К чему скитаться розно?\nОбнимемся в пути.\nТеперь ещё не поздно\nНа палубу взойти».\nЧто означает слово розно?","choices":["по морям","подолгу","поодиночке","понемногу","по заграницам"],"key":"В","review":["Что значит «розно»","Лирический герой предлагает обняться в пути. Перед этим он спрашивает, зачем скитаться отдельно.","«Розно» значит «порознь», «поодиночке»."]},{"author":"И. Рубанов","question":"Сколько орфографических ошибок сделал Вовочка в предложении Циган купил красовки?","choices":["0","1","2","3","4"],"key":"Г","review":["Орфография в диктанте","В слове «цыган» после ц пишется ы. Это известное исключение.","«Кроссовки» пишутся с о в первом слоге и с двойной с. Всего три ошибки в предложении."]},{"author":"К. Кноп","question":"В русском языке есть два разных глагола жать. Значение одного из них — ‘давить’. Найдите в списке ответов значение второго глагола.","choices":["полоть сорняки","вести трактор","срезать стебли злаков","сеять","среди вариантов (А)–(Г) нет правильного"],"key":"В","review":["Одинаково звучащие глаголы","«Жать на кнопку» — давить, нажимать. Другой глагол встречается в выражениях «жать рожь», «жать пшеницу».","Он означает срезать стебли злаков во время жатвы."]},{"author":"Е. Муравенко","question":"Какие варианты из перечисленных можно поставить вместо многоточия во фразе Результаты моих первых работ были ..., чем сейчас: 1) слабее, 2) более слабее, 3) слабже, 4) более слабыми?","choices":["1, 2","1, 3","1, 4","1, 2, 4","1, 3, 4"],"key":"В","review":["Сравниваем без лишнего слова","Простая сравнительная форма — «слабее». Также допустимо «более слабыми».","«Более слабее» дважды выражает сравнение, а «слабже» — неверная форма. Подходят позиции 1 и 4."]},{"author":"К. Кноп","question":"Исключите слово, которое означает не такой вид растительности, как все остальные слова из списка:","choices":["джунгли","ельник","бор","луг","дубрава"],"key":"Г","review":["Деревья или травы","Джунгли, ельник, бор и дубрава — виды леса или древесной растительности.","На лугу растут прежде всего травы. Поэтому луг отличается от остальных."]},{"author":"Л. Фёдорова","question":"Владелец киоска задумался, как подписать этикетку к Orbit. Помогите ему выбрать верный вариант:","choices":["жевачка","жувачка","живачка","жвачка","жывачка"],"key":"Г","review":["Правильное написание","Слово происходит от «жевательная резинка», но в коротком разговорном названии первый слог сокращён.","Пишется «жвачка», без дополнительной гласной между ж и в."]},{"author":"Е. Муравенко","question":"Строчка из известной песенки Жил-был у бабушки серенький козлик в зашифрованном виде выглядит так: Шыр-пир ю пяпюжгы зэлэмъгый гёсрыг. А как с помощью этого же шифра записать Крокодил Гена?","choices":["Клёкотыр Гэмя","Глёгётыр Кэня","Клёкётыр Гэмя","Глёгёдыр Кэмя","Глёгётыр Кэмя"],"key":"Д","review":["Заменяем буквы по образцу","Шифр попарно меняет буквы: к ↔ г, р ↔ л, д ↔ т, н ↔ м; о ↔ ё, и ↔ ы, е ↔ э и а ↔ я. Эти соответствия видны в примере или восстанавливаются по парам.","«Крокодил» даёт «Глёгётыр», а «Гена» — «Кэмя». Верно только в варианте Д."]},{"author":"Е. Муравенко","question":"Кто написал произведение, название которого здесь зашифровано?","choices":["Пушкин","Крылов","Ершов","Чуковский","Маршак"],"key":"Б","review":["Название в рисунках","У «лист» убери конечную т, у «лица» — начальную л. Получаются «лис» и «ица», вместе «лисица».","Буквенные знаки перед этим дают «ворона и». Басню «Ворона и Лисица» написал Иван Крылов."],"figure":{"condition":{"src":"assets/medvezhonok/2001/3-5-12-rebus.webp","alt":"Ребус. В большой букве О находятся другие буквы, рядом О над И. Затем лист с запятой справа и три лица с запятой слева.","width":689,"height":157}}},{"author":"Л. Фёдорова","question":"Вот список существительных: 1) очи, 2) бигуди, 3) жалюзи, 4) усы, 5) санки, 6) лыжи, 7) коньки, 8) каникулы. У каких из них нет формы единственного числа?","choices":["5, 6, 7","5, 6, 7, 8","3, 5, 8","2, 3, 5, 8","1, 2, 3, 5, 8"],"key":"Г","review":["У каких слов нет пары","К «очи», «усы», «лыжи» и «коньки» можно подобрать формы «око», «ус», «лыжа» и «конёк».","Бигуди, жалюзи, санки и каникулы не имеют обычного единственного числа. Это 2, 3, 5 и 8."]},{"author":"У. Синицына","question":"Какие из этих слов обозначают группу людей: 1) толпа; 2) гурьба; 3) стадо; 4) орава; 5) стая?","choices":["1, 4, 5","1, 2, 4","все","2, 4","1, 4, 5"],"key":"Б","review":["Как зовут группу","Толпа, гурьба и орава обычно обозначают скопление людей.","Стадо и стая называют группы животных. Подходят пункты 1, 2 и 4."]},{"author":"Е. Муравенко","question":"Даны предложения:\n1) В соревновании участвовали ученики обоих школ.\n2) Скоро зажгётся фонарь и осветит улицу.\n3) Внимательно слушав учителя, он всё усваивал.\nПеречислите те из них, которые содержат ошибки в образовании слов.","choices":["1","2","2, 3","1, 2","1, 2, 3"],"key":"Д","review":["Правильные формы слов","В первой фразе нужны «обеих школ», во второй — «зажжётся фонарь».","В третьей для одновременно идущих действий нужно «слушая учителя». Таким образом, исправления нужны во всех трёх."]},{"author":"Е. Муравенко","question":"Какое из этих слов по смыслу существенно отличается от остальных?","choices":["буран","ураган","вьюга","метель","пурга"],"key":"Б","review":["Ветер со снегом или без него","Буран, вьюга, метель и пурга связаны со снегом, который переносит ветер.","Ураган — очень сильный ветер. Снег для урагана не обязателен."]},{"author":"Л. Фёдорова","question":"Какие из этих слов происходят от того же корня, что и слово стол: 1) столовая, 2) столица, 3) столяр, 4) столько, 5) столешница, 6) столетник, 7) престол, 8) застолье?","choices":["все","все, кроме 4, 7","все, кроме 4, 5","все, кроме 4, 6","все, кроме 4, 5, 6"],"key":"Г","review":["Родство со словом «стол»","Столовая, столяр, столешница и застолье прямо связаны со столом. «Престол» и «столица» связаны со старым смыслом «стола» как княжеского места.","«Столько» относится к количеству, «столетник» — к ста годам. Они имеют другие корни."]},{"author":"Л. Фёдорова","question":"В каких словах на месте многоточия пишется е: 1) в...сеть, 2) на в...су, 3) зав...сать, 4) занав...с, 5) в...сячий?","choices":["2","2, 4","2, 3, 4","4","1, 2, 4, 5"],"key":"Б","review":["Висеть, но на весу","Пишут «висеть», «зависать» и «висячий» с и.","В сочетании «на весу» и слове «занавес» нужна е. Подходят пункты 2 и 4."]},{"author":"Л. Фёдорова","question":"Как начинается поговорка: «...видит издалека»?","choices":["моряк моряка","рыбак рыбака","рыбак моряка","свояк свояка","дурак дурака"],"key":"Б","review":["Как узнают своего","Привычная поговорка звучит «рыбак рыбака видит издалека».","Так говорят о людях с общим делом или интересами, которые быстро узнают друг друга."]},{"author":"Е. Муравенко","question":"Даны формы слов: туч, лож, душ, туш, плач. Сколько получится осмысленных слов, если к каждому данному слову добавить букву ь?","choices":["1","2","3","4","5"],"key":"В","review":["Добавляем мягкий знак","«Лож» превращается в «ложь», «туш» — в «тушь», «плач» — в «плачь».","Для форм «туч» и «душ» добавление ь не даёт обычного слова. Получается три слова."]},{"author":"И. Рубанов","question":"В старой песне поётся:\n«По-армянски Ованес,\nА по-русски – Ваня.»\nА как по-испански?","choices":["Иоанн","Ян","Жан","Хуан","Юхан"],"key":"Г","review":["Имя по-испански","Армянское Ованес и русское Иван — традиционные формы одного имени.","Его испанская форма — Хуан. Жан, Ян и Юхан относятся к другим языкам."]},{"author":"Л. Фёдорова","question":"У вас с другом отцы хорошо знакомы и в приятельских отношениях. Дополните фразу: Они друг с другом ...","choices":["на равной ноге","на короткой ноге","на близкой ноге","на одной ноге","на двух ногах"],"key":"Б","review":["Приятельский оборот","Фраза «быть на короткой ноге» означает близкое и непринуждённое знакомство.","Она подходит про отцов, которые хорошо знакомы и общаются по-приятельски."]},{"author":"Л. Фёдорова","question":"В русском языке некоторые имена и понятия неразрывно связаны: скажешь Трифон — и тут же вспомнится Тришкин кафтан. Вот четыре имени: Кузьма, Сидор, Макар, Демьян. Какое из пяти перечисленных ниже слов не связано в фольклоре ни с одним из них?","choices":["мать","сын","коза","телята","ухá"],"key":"Б","review":["Имена и пословицы","Есть «Кузькина мать», «Сидорова коза», «куда Макар телят не гонял» и «Демьянова уха».","Сын ни в одном из этих выражений не упоминается. Это лишнее слово."]},{"author":"Е. Муравенко","question":"Слово лёгкий многозначно, поэтому имеет несколько антонимов. Подберите то существительное, в сочетании с которым антонимом к слову лёгкий будет серьёзный.","choices":["чемодан","урок","ветер","музыка","мужчина"],"key":"Г","review":["Антонимы слова «лёгкий»","Чемодан бывает лёгким или тяжёлым, а ветер — лёгким или сильным.","О музыке говорят «лёгкая» и «серьёзная». Здесь речь о характере музыки."]},{"author":"И. Рубанов","question":"Имя Виктор означает:","choices":["победитель","могучий","славный","загадочный","воин"],"key":"А","review":["Значение латинского имени","Имя «Виктор» происходит от латинского victor. Это слово родственно английскому victory — «победа».","В латыни victor называли того, кто одержал победу. Значение имени — «победитель»."]},{"author":"У. Синицына","question":"Вот пять несклоняемых существительных: 1) кофе, 2) шимпанзе, 3) кашне, 4) какаду, 5) пальто. Какие из них можно употребить вместо многоточия в словосочетании «чёрный ...»?","choices":["2, 4","1, 3","1, 2, 5","1, 2, 4","1, 2, 3, 4"],"key":"Г","review":["Род заимствованных слов","В литературной норме «чёрный кофе». «Шимпанзе» и «какаду» без уточнения пола тоже обычно мужского рода.","«Кашне» и «пальто» среднего рода: «чёрное кашне», «чёрное пальто». Подходят 1, 2 и 4."],"reviewedEdition":true},{"author":"Л. Фёдорова","question":"Какие из десяти перечисленных слов происходят от названий частей человеческого тела: 1) подножка, 2) подушка, 3) подзатыльник, 4) подворотня, 5) поручение, 6) намордник, 7) на запятках, 8) наручники, 9) лапник, 10) прохвост?","choices":["все","все, кроме 4","все, кроме 4, 9, 10","все, кроме 4, 6, 9, 10","1, 2, 5, 7, 8"],"key":"Г","review":["Части тела внутри слов","Узнаются «нога», «затылок», «рука» и «пята». В ключе также принято объяснение «подушки» как предмета под ухо.","«Подворотня» связана с воротами, «намордник» — с мордой, «лапник» — с еловыми лапами. «Прохвост» происходит от слова «профос», названия должности. «Подушку» этимологи также связывают со словами «дух» и «надувать»."]},{"author":"Л. Фёдорова","question":"Даны десять существительных: 1) дуло, 2) рыло, 3) шило, 4) крыло, 5) жало, 6) покрывало, 7) помело, 8) чернила, 9) кило, 10) пила. Какие из них образованы от глаголов с помощью суффикса -л-(о/а)?","choices":["все, кроме 9","все, кроме 9, 10","все, кроме 4, 9, 10","все, кроме 4, 5, 9, 10","все, кроме 4, 5, 7, 9, 10"],"key":"Г","review":["Глагольная основа и «-л-»","Сопоставь «ду́ло — дуть», «ры́ло — рыть», «ши́ло — шить», «покрыва́ло — покрывать», «помело́ — помести», «чернила — чернить». Они образованы по указанному правилу.","«Крыло», «жало», «кило» и «пила» по такому правилу от русских глаголов не образованы. «Жалить», например, связано с названием «жало»."]},{"author":"И. Рубанов","question":"Какое слово надо подставить вместо многоточия во фразу: Нас не устраивает уровень двусторонних отношений наших стран, и мы сделаем всё для его ...?","choices":["активизации","усиления","укрепления","улучшения","повышения"],"key":"Д","review":["Сочетание со словом «уровень»","В местоимении «его» имеется в виду уровень, а не сами отношения.","Уровень повышают. Активизировать или укреплять можно отношения, но не сам их уровень."]},{"author":"Л. Кандинский","question":"По-итальянски спасать — salvare, спасаю — salvo, говоришь — parli, пою — canto, говорить — parlare, поёшь — canti. Как по-итальянски будет петь и спасаешь?","choices":["cantore и salve","canti и salvare","cantare и salvi","canto и salvo","cantare и salva"],"key":"В","review":["Личные формы по-итальянски","По salvare и parlare видно, что неопределённая форма оканчивается на -are. От canto получаем cantare — «петь».","Форма для «ты» оканчивается на -i, как parli и canti. Поэтому «спасаешь» — salvi."]}], {"year":2001,"grade":"3-5","tasksFile":"3-5.pdf","answersFile":"3-5-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2001.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
